export interface WifiNetwork {
  ssid: string
  signal: number
  security: 'WPA2' | 'WPA3' | 'Open'
  connected: boolean
}

/** Simulated networking: no real traffic is ever generated by this model. */
export class NetworkModel {
  wifiEnabled = true
  airplaneMode = false
  networks: WifiNetwork[] = [
    { ssid: 'HomeNet-5G', signal: 92, security: 'WPA3', connected: true },
    { ssid: 'HomeNet-2.4G', signal: 78, security: 'WPA2', connected: false },
    { ssid: 'CoffeeShop-Guest', signal: 54, security: 'Open', connected: false },
    { ssid: 'UEM-Kolkata', signal: 47, security: 'WPA2', connected: false },
    { ssid: 'NeighborWiFi', signal: 31, security: 'WPA2', connected: false },
  ]

  get connectedNetwork(): WifiNetwork | undefined {
    return this.networks.find((n) => n.connected)
  }
  get online(): boolean {
    return this.wifiEnabled && !this.airplaneMode && !!this.connectedNetwork
  }
  connect(ssid: string): boolean {
    const n = this.networks.find((x) => x.ssid === ssid)
    if (!n) return false
    for (const x of this.networks) x.connected = false
    n.connected = true
    return true
  }
  disconnect(): void {
    for (const x of this.networks) x.connected = false
  }
}

export const networkModel = new NetworkModel()
